// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerReminder, createCollection, dragFieldRowAndWaitForSave } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(145000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/logout`);
    await page.goto(baseUrl);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));
    await dismissProjectOwnerReminder(page);
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);

    const playwrightRequest1: Record<string, any> = {"collection": `sr_field_order_${Date.now()}`};

    await createCollection(page, getValue(playwrightRequest1, "collection"));

    await dragFieldRowAndWaitForSave(page, 360, 285, 360, 130, 25);

    // The PR under test adds notify({ title: t('field_order_saved'), type: 'success' }) at the end
    // of setSort(), so a success toast confirms the reorder was saved.
    await expect(page.locator('.notification-item.success')).toContainText('Field order saved');

    // The reorder took effect: "sort" was dragged from last position to first, so the list is
    // now sort, id, status.
    await expect(page.locator('.field-grid > *').first()).toContainText('sort');
    await expect(page.locator('.field-grid > *').last()).toContainText('status');

    // The save succeeded, so Directus' "Unexpected Error" dialog is not shown.
    await expect(page.getByText('Network Error')).toHaveCount(0);
});
